import React, { useState } from 'react';
import './Checkout.css';

const Checkout = ({ cart, total, onClose, onSuccess }) => {
  const [deliveryAddress, setDeliveryAddress] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('dinheiro');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [orderId, setOrderId] = useState(null);

  const [cardData, setCardData] = useState({
    cardNumber: '',
    cardHolder: '',
    expiryMonth: '',
    expiryYear: '',
    cvv: ''
  });

  const token = localStorage.getItem('authToken');

  const createOrder = async () => {
    try {
      const response = await fetch('http://localhost:3001/api/orders', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          items: cart.map(item => ({
            product_id: item.id,
            quantity: item.quantity,
            price: parseFloat(item.price)
          })),
          total: parseFloat(total),
          delivery_address: deliveryAddress
        })
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'Erro ao criar pedido');
      }

      const data = await response.json();
      return data.id;
    } catch (err) {
      throw err;
    }
  };

  const processCardPayment = async (paymentOrderId) => {
    try {
      if (!cardData.cardNumber || !cardData.cardHolder || !cardData.expiryMonth || !cardData.expiryYear || !cardData.cvv) {
        throw new Error('Preencha todos os dados do cartão');
      }

      console.log('📤 Enviando pagamento com orderId:', paymentOrderId);

      const response = await fetch('http://localhost:3001/api/payments/charge', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          cardNumber: cardData.cardNumber,
          cardHolder: cardData.cardHolder,
          expiryMonth: cardData.expiryMonth,
          expiryYear: cardData.expiryYear,
          cvv: cardData.cvv,
          amount: parseFloat(total),
          orderId: paymentOrderId
        })
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || data.message || 'Erro ao processar pagamento');
      }

      const data = await response.json();
      return data;
    } catch (err) {
      throw err;
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!deliveryAddress.trim()) {
      setError('Digite o endereço de entrega');
      setLoading(false);
      return;
    }

    try {
      console.log('📦 Criando pedido...');
      const newOrderId = await createOrder();
      console.log('✅ ID do pedido recebido:', newOrderId);
      setOrderId(newOrderId);

      if (paymentMethod === 'cartao') {
        console.log('💳 Processando pagamento com Stone...');
        const paymentResult = await processCardPayment(newOrderId);
        console.log('✅ Pagamento aprovado:', paymentResult);
      } else if (paymentMethod === 'pix') {
        console.log('📱 PIX - Em desenvolvimento');
      } else {
        console.log('💵 Dinheiro - Pagamento na entrega');
      }

      setSuccess(true);
      setTimeout(() => {
        onSuccess();
      }, 2000);
    } catch (err) {
      setError(err.message);
      console.error('❌ Erro:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCardChange = (e) => {
    const { name, value } = e.target;
    setCardData({
      ...cardData,
      [name]: value
    });
  };

  if (success) {
    return (
      <div className="checkout-modal">
        <div className="checkout-content">
          <div className="success-message">
            <h2>✅ Pedido #{orderId} Criado!</h2>
            <p>Seu pedido foi confirmado com sucesso!</p>
            {paymentMethod === 'cartao' && <p>💳 Pagamento aprovado</p>}
            {paymentMethod === 'dinheiro' && <p>💵 Pagamento na entrega</p>}
            <p>Você pode acompanhar o status em "Meus Pedidos"</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="checkout-modal">
      <div className="checkout-content">
        <button className="close-btn" onClick={onClose}>×</button>
        
        <h2>Finalizar Pedido</h2>

        <div className="checkout-summary">
          <h3>📦 Resumo do Carrinho</h3>
          <div className="order-items">
            {cart.map(item => (
              <div key={item.id} className="order-item">
                <span>{item.name} x{item.quantity}</span>
                <span>R$ {(parseFloat(item.price) * item.quantity).toFixed(2)}</span>
              </div>
            ))}
          </div>
          <div className="order-total">
            <strong>Total: R$ {parseFloat(total).toFixed(2)}</strong>
          </div>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>📍 Endereço de Entrega:</label>
            <input
              type="text"
              value={deliveryAddress}
              onChange={(e) => setDeliveryAddress(e.target.value)}
              placeholder="Digite seu endereço completo"
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label>💳 Método de Pagamento:</label>
            <div className="payment-methods">
              <label className="payment-option">
                <input
                  type="radio"
                  name="paymentMethod"
                  value="dinheiro"
                  checked={paymentMethod === 'dinheiro'}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  disabled={loading}
                />
                <span>💵 Dinheiro (na entrega)</span>
              </label>
              <label className="payment-option">
                <input
                  type="radio"
                  name="paymentMethod"
                  value="cartao"
                  checked={paymentMethod === 'cartao'}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  disabled={loading}
                />
                <span>💳 Cartão de Crédito/Débito</span>
              </label>
              <label className="payment-option">
                <input
                  type="radio"
                  name="paymentMethod"
                  value="pix"
                  checked={paymentMethod === 'pix'}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  disabled={loading}
                />
                <span>📱 PIX (em breve)</span>
              </label>
            </div>
          </div>

          {paymentMethod === 'cartao' && (
            <div className="card-form">
              <h4>Dados do Cartão</h4>
              
              <div className="form-group">
                <label>Número do Cartão:</label>
                <input
                  type="text"
                  name="cardNumber"
                  placeholder="0000 0000 0000 0000"
                  value={cardData.cardNumber}
                  onChange={handleCardChange}
                  maxLength="19"
                  disabled={loading}
                  required
                />
              </div>

              <div className="form-group">
                <label>Nome do Titular:</label>
                <input
                  type="text"
                  name="cardHolder"
                  placeholder="NOME COMPLETO"
                  value={cardData.cardHolder}
                  onChange={handleCardChange}
                  disabled={loading}
                  required
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Mês de Validade:</label>
                  <input
                    type="number"
                    name="expiryMonth"
                    placeholder="MM"
                    value={cardData.expiryMonth}
                    onChange={handleCardChange}
                    min="1"
                    max="12"
                    disabled={loading}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Ano de Validade:</label>
                  <input
                    type="number"
                    name="expiryYear"
                    placeholder="YYYY"
                    value={cardData.expiryYear}
                    onChange={handleCardChange}
                    min={new Date().getFullYear()}
                    disabled={loading}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>CVV:</label>
                  <input
                    type="password"
                    name="cvv"
                    placeholder="000"
                    value={cardData.cvv}
                    onChange={handleCardChange}
                    maxLength="4"
                    disabled={loading}
                    required
                  />
                </div>
              </div>

              <p className="card-warning">⚠️ Seus dados são seguros e processados pela Stone</p>
            </div>
          )}

          {error && <div className="error-message">❌ {error}</div>}

          <button type="submit" disabled={loading || cart.length === 0}>
            {loading ? '⏳ Processando...' : '✅ Confirmar Pedido'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Checkout;
